"""Root fillet generated by the rack (hob) in the tooth form used by the exporters and the FEM."""

from __future__ import annotations

import warnings
from dataclasses import replace
from math import cos, radians, sqrt

import numpy as np
import pytest

from gearbox.export.exporters import _build_wheel
from gearbox.profile import ToothProfile
from gearbox.standards.iso6336 import bending
from tests.scenarios import build_transmission


def _transmission(**kwargs):
    with warnings.catch_warnings():
        warnings.simplefilter("ignore")
        return build_transmission(**kwargs)


def _form(gear) -> np.ndarray:
    return np.asarray(_build_wheel(gear).formcoords, dtype=float)


def _tangent_angles(form: np.ndarray) -> np.ndarray:
    """Angle [deg] between each segment and the tooth axis (y)."""
    step = np.diff(form, axis=0)
    return np.degrees(np.arctan2(np.abs(step[:, 0]), np.abs(step[:, 1])))


def _critical_section(form: np.ndarray) -> tuple[float, float]:
    """Chord ``s_Fn`` and fillet radius ``rho_F`` where the tangent makes 30 deg with the axis."""
    angles = _tangent_angles(form)
    radius = np.hypot(form[:, 0], form[:, 1])
    fillet = np.nonzero(radius[1:] < radius.max() * 0.999)[0]
    # first segment, from the root, whose tangent is steeper than 30 deg
    k = next(i for i in fillet if angles[i] < 30.0 and radius[i] > radius.min() * 1.0001)
    t = (angles[k - 1] - 30.0) / (angles[k - 1] - angles[k])
    mid = lambda i: (form[i] + form[i + 1]) / 2  # noqa: E731
    point = mid(k - 1) + t * (mid(k) - mid(k - 1))
    a, b, c = form[k - 1], form[k], form[k + 1]
    u, v = b - a, c - a
    area = abs(u[0] * v[1] - u[1] * v[0]) / 2
    rho = np.linalg.norm(b - a) * np.linalg.norm(c - b) * np.linalg.norm(c - a) / (4 * area)
    return 2 * abs(point[0]), rho


@pytest.mark.parametrize("x1", [0.0, 0.525, -0.2])
def test_critical_section_matches_iso6336_3(x1):
    # ISO 6336-3:2019 formulae (23)-(25) give s_Fn and rho_F of the fillet generated by the rack
    t = _transmission(x1=x1, x2=0.0)
    root = bending._tooth_root_geometry(t, t.pinion)
    chord, rho = _critical_section(_form(t.pinion))
    assert chord == pytest.approx(root.tooth_root_chord, rel=2e-3)
    assert rho == pytest.approx(root.root_fillet_radius, rel=2e-2)


@pytest.mark.parametrize(("x1", "helix"), [(0.0, 0.0), (0.525, 0.0), (0.0, 15.0), (0.3, 25.0)])
def test_fillet_joins_root_and_flank_tangentially(x1, helix):
    form = _form(_transmission(x1=x1, x2=0.0, helix_angle=helix).pinion)
    radius = np.hypot(form[:, 0], form[:, 1])
    below_tip = radius < radius.max() - 1e-6
    angles = _tangent_angles(form[below_tip])
    assert np.max(np.abs(np.diff(angles))) < 3.0


def test_root_and_form_diameters_follow_the_rack():
    t = _transmission(x1=0.0, x2=0.0)
    data = _build_wheel(t.pinion).data
    form = _form(t.pinion)
    m, z, x = 2.5, 22, 0.0
    assert 2 * np.hypot(*form.T).min() == pytest.approx(m * z - 2 * m * (1.25 - x), abs=1e-9)
    # the lowest point of the straight tool flank, ``lead`` below the rolling line, generates
    # the start of the involute, ``lead / sin(alpha)`` from the pitch point on the line of action
    alpha = radians(20.0)
    rb = m * z * cos(alpha) / 2
    lead = (1.25 - 0.38 * (1 - np.sin(alpha)) - x) * m
    expected = 2 * sqrt(rb**2 + (rb * np.tan(alpha) - lead / np.sin(alpha)) ** 2)
    assert data["d_Ff"] == pytest.approx(expected, rel=1e-6)


def _gear(**changes):
    return replace(_transmission().pinion, **changes)


def test_helical_fillet_is_generated_in_the_transverse_section():
    profile = ToothProfile(_gear(number_of_teeth=30, module=2.0, helix_angle=20.0))
    assert profile.data["d_Ff"] > profile.data["d_f"]
    # the root and tip diameters are those of the gear model
    gear = _gear(number_of_teeth=30, module=2.0, helix_angle=20.0)
    assert profile.data["d_f"] == pytest.approx(gear.root_diameter)
    assert profile.data["d_a"] == pytest.approx(gear.tip_diameter)


def test_undercut_gear_keeps_a_valid_profile():
    with pytest.warns(UserWarning, match="undercut"):
        profile = ToothProfile(
            _gear(number_of_teeth=10, module=2.0, profile_shift_coefficient=0.0, shaft_diameter=8.0)
        )
    form = np.asarray(profile.formcoords, dtype=float)
    radius = np.hypot(form[:, 0], form[:, 1])
    assert np.all(np.diff(radius[radius < radius.max() - 1e-9]) > -1e-9)
    assert profile.data["d_Ff"] > profile.data["d_b"]


def test_half_tooth_runs_from_the_gap_to_the_tip():
    gear = _gear(profile_shift_coefficient=0.0)
    profile = ToothProfile(gear)
    form = np.asarray(profile.formcoords)
    # starts on the root circle in the middle of the gap, ends on the tooth axis at the tip
    assert np.hypot(*form[0]) == pytest.approx(gear.root_diameter / 2)
    assert np.arctan2(-form[0, 0], form[0, 1]) == pytest.approx(np.pi / gear.number_of_teeth)
    assert form[-1] == pytest.approx([0.0, gear.tip_diameter / 2])
    assert np.all(form[:-1, 0] < 0)
    # the flank is the involute: tooth thickness on the reference circle s = m (pi/2 + 2 x tan a)
    radius = np.hypot(form[:, 0], form[:, 1])
    angle = np.arctan2(-form[:, 0], form[:, 1])
    flank = (radius > profile.data["d_Ff"] / 2) & (radius < gear.tip_diameter / 2 - 1e-9)
    order = np.argsort(radius[flank])
    half = np.interp(gear.reference_diameter / 2, radius[flank][order], angle[flank][order])
    assert 2 * half * gear.reference_diameter / 2 == pytest.approx(
        np.pi * gear.module / 2, rel=1e-5
    )


def test_internal_gears_are_refused():
    with pytest.raises(ValueError, match="external"):
        ToothProfile(_gear(internal=True, number_of_teeth=60, profile_shift_coefficient=0.0))
